// ---- Candidate 1: deletion commands receive no OPENCODE_DB / --dir while
// runs are DB-isolated via metadata opencode.database_path. ----

func TestDeletionCommandsLackStoreDBWiring(t *testing.T) {
	dir := t.TempDir()
	recording := filepath.Join(dir, "invocations.txt")
	script := "#!/bin/sh\n{ echo \"ARGV: $@\"; env | grep -E '^OPENCODE_DB=' || echo 'OPENCODE_DB: <unset>'; echo '---'; } >> " + recording + "\nexit 0\n"
	exe := filepath.Join(dir, "fake-opencode")
	if err := os.WriteFile(exe, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	var cfg config.Config
	cfg.Agentwrap.Executable = exe

	storePath := ScopedRuntimeStorePath(dir, "sprint:p:s:review:cov1::")
	if err := prepareRuntimeStore(storePath, "sprint:p:s:review:cov1::"); err != nil {
		t.Fatal(err)
	}

	// Show what a RUN subprocess would receive for this store (SDK contract:
	// metadata opencode.database_path -> OPENCODE_DB), then what the deletion
	// hook actually executes.
	req := Request{Prompt: "x", RuntimeStorePath: storePath, RuntimeStoreOwner: "sprint:p:s:review:cov1::"}
	awReq, err := toAgentwrapRequest(req)
	if err != nil {
		t.Fatal(err)
	}
	gotDB := awReq.Metadata["opencode_database_path"]
	if gotDB != storePath {
		t.Fatalf("run metadata database path = %q, want %q", gotDB, storePath)
	}

	adapter, err := NewOpenCode(cfg)
	if err != nil {
		t.Fatal(err)
	}
	if err := adapter.DeleteSessions(context.Background(), []string{"sess-1", ""}); err != nil {
		t.Fatalf("DeleteSessions: %v", err)
	}
	data, err := os.ReadFile(recording)
	if err != nil {
		t.Fatal(err)
	}
	text := string(data)
	t.Logf("deletion invocations:\n%s", text)
	if strings.Contains(text, "OPENCODE_DB="+storePath) {
		t.Fatalf("deletion unexpectedly targeted the scoped store DB")
	}
	if !strings.Contains(text, "OPENCODE_DB: <unset>") {
		t.Fatalf("expected OPENCODE_DB unset in deletion environment, got:\n%s", text)
	}
	if !strings.Contains(text, "ARGV: db DELETE FROM event_sequence WHERE aggregate_id = 'sess-1'") {
		t.Fatalf("unexpected argv: %s", text)
	}
	if strings.Contains(text, "--dir") {
		t.Fatalf("deletion passes no --dir alignment either:\n%s", text)
	}
}

// ---- Candidate 1b: checkpoint success parser is sensitive to output shape;
// JSON-shaped output burns 20 retries (~5s) and fails the whole batch. ----

func TestCheckpointParserFailsOnJSONOutput(t *testing.T) {
	dir := t.TempDir()
	script := "#!/bin/sh\nif [ \"$2\" = \"--format\" ]; then echo '[[0,-1,-1]]'; else echo '[[0,-1,-1]]'; fi\n"
	exe := filepath.Join(dir, "fake-opencode")
	if err := os.WriteFile(exe, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	var cfg config.Config
	cfg.Agentwrap.Executable = exe
	start := time.Now()
	err := checkpointOpenCode(context.Background(), cfg)
	elapsed := time.Since(start)
	if err == nil {
		t.Fatalf("expected busy failure for non-table output")
	}
	if elapsed < 4*time.Second {
		t.Fatalf("expected ~5s retry burn, took %v", elapsed)
	}
	t.Logf("checkpoint error after %v: %v", elapsed, err)
}

func TestCheckpointParserSucceedsOnTableOutput(t *testing.T) {
