		Checks:         []string{"runtime_available"},
		RequiredChecks: []string{"runtime_available"},
		Capabilities:   []string{"permissions"},
	})
	if err != nil {
		t.Fatalf("Health returned error despite failing required-capability probe: %v", err)
	}
	if report.Status != string(agentwrap.HealthReady) {
		t.Logf("status=%q", report.Status)
	}
	if len(report.Capabilities) != 0 {
		t.Fatalf("capability checks = %+v, expected none (enforcement skipped)", report.Capabilities)
	}
	t.Logf("report: ready=%v caps=%v err=nil — required capability 'permissions' never evaluated", report.Status, report.Capabilities)
}

// ---- Candidate 6: active stores with a live-but-reused PID survive even
// aggressive GC regardless of age. ----

func TestActiveStoreWithLivePIDNeverRemovedDespiteAge(t *testing.T) {
	root := t.TempDir()
	path := ScopedRuntimeStorePath(root, "crashed-long-ago")
	if err := prepareRuntimeStore(path, "crashed-long-ago"); err != nil {
		t.Fatal(err)
	}
	record, err := loadRuntimeStoreRecord(filepath.Dir(path))
	if err != nil {
		t.Fatal(err)
	}
	record.PID = os.Getpid() // live PID (as if reused by another process)
	record.UpdatedAt = time.Now().Add(-365 * 24 * time.Hour)
	if err := writeRuntimeStoreRecord(filepath.Dir(path), record); err != nil {
		t.Fatal(err)
	}
	summary := CleanupRuntimeStores(root, 72*time.Hour, 0, true)
	if len(summary.Removed) != 0 {
		t.Fatalf("aggressive GC removed an active store: %+v", summary)
	}
	stores, err := InspectRuntimeStores(root)
	if err != nil || len(stores) != 1 {
		t.Fatalf("stores=%+v err=%v", stores, err)
	}
	t.Logf("year-old active store with unrelated live PID survived aggressive GC; quota path also requires state!=active")
}

// ---- Candidate 4: OnEvent keeps firing after StartRun returns via the 5s
// synthesized-cancel branch. ----

type lingeringRun struct {
	id      agentwrap.RunID
	events  chan agentwrap.Event
	cancel  chan struct{}
	cancelled chan struct{}
}

func newLingeringRun() *lingeringRun {
	return &lingeringRun{
		id:        "run-late",
		events:    make(chan agentwrap.Event),
		cancel:    make(chan struct{}),
		cancelled: make(chan struct{}),
	}
}

func (f *lingeringRun) ID() agentwrap.RunID { return f.id }
func (f *lingeringRun) Events() <-chan agentwrap.Event {
	go func() {
		select {
		case <-f.cancel:
			close(f.events)
		case <-f.cancelled:
			close(f.events)
		}
	}()
	return f.events
}
func (f *lingeringRun) Wait(ctx context.Context) (agentwrap.RunResult, error) {
	<-ctx.Done()
	return agentwrap.RunResult{Status: agentwrap.StatusCancelled}, ctx.Err()
}
func (f *lingeringRun) Cancel(context.Context) error {
	close(f.cancelled)
	return nil
}

type lateProbeRuntime struct{ run *lingeringRun }

func (p lateProbeRuntime) StartRun(context.Context, agentwrap.RunRequest) (agentwrap.Run, error) {
	return p.run, nil
}
func (p lateProbeRuntime) Capabilities(context.Context) (agentwrap.Capabilities, error) {
	return agentwrap.Capabilities{}, nil
}

func TestOnEventFiresAfterStartRunReturnsViaGraceBranch(t *testing.T) {
	run := newLingeringRun()
	adapter := NewAdapter(lateProbeRuntime{run: run})
	ctx, cancel := context.WithCancel(context.Background())

	var mu sync.Mutex
	postReturn := 0
	done := make(chan struct{})
	first := make(chan struct{})
	req := Request{Prompt: "hello", OnEvent: func(Event) {
		mu.Lock()
		postReturn++
		mu.Unlock()
		select {
		case <-first:
		default:
			close(first)
		}
	}}

	type outcome struct {
		res Result
		err error
	}
	outcomeCh := make(chan outcome, 1)
	go func() {
		res, err := adapter.StartRun(ctx, req)
		outcomeCh <- outcome{res, err}
	}()
	time.Sleep(100 * time.Millisecond) // let StartRun block in Wait
	cancel()                           // trigger ctx.Done -> Cancel + 5s grace
	out := <-outcomeCh
	if out.err == nil {
		t.Fatalf("expected cancellation error")
	}

	// StartRun has returned the synthesized cancelled result; now emit a late event.
	run.events <- agentwrap.Event{ID: "late-1", RunID: "run-late", Type: "native.message"}
	select {
	case <-first:
		mu.Lock()
		defer mu.Unlock()
		t.Logf("OnEvent invoked %d time(s) AFTER StartRun returned a terminal result", postReturn)
	case <-time.After(2 * time.Second):
		t.Log("no late callback observed")
	}
	close(run.cancel)
	<-done
	_ = done
}

// ---- Candidate 3: redaction inconsistency across mapped diagnostics. ----

func TestDiagnosticsRedactionInconsistency(t *testing.T) {
	secret := "leak api_key=[REDACTED] here"
	result := mapResult(agentwrap.RunResult{
		Warnings: []string{secret},
		Metadata: agentwrap.RunMetadata{
			Policy: agentwrap.PolicyMetadata{
				ExhaustedReason: secret,
				Decisions:       []agentwrap.PolicyDecisionRecord{{Reason: secret, Detail: secret}},
			},
			Validation: agentwrap.ValidationMetadata{Final: agentwrap.ValidationResult{
				Failures: []agentwrap.ValidationFinding{{Observed: secret}},
			}},
			Repair: agentwrap.RepairMetadata{ExhaustedReason: secret},
		},
	})
	checks := map[string]struct {
		value     string
		truncated bool
	}{
		"warning":                {result.Warnings[0], false},
		"policy.exhausted":       {result.Policy.ExhaustedReason, false},
		"policy.decision.reason": {result.Policy.Decisions[0].Reason, false},
		"validation.detail":      {result.Validation.Details[0], false},
		"repair.exhausted":       {result.Repair.ExhaustedReason, false},
	}
	for label, c := range checks {
		redacted := c.value == "[REDACTED]"
		t.Logf("%-24s redacted=%v truncated=%v value=%q", label, redacted, c.truncated, c.value)
		if redacted {
			t.Errorf("%s was unexpectedly redacted (inconsistency direction flipped?)", label)
		}
	}
	// Contrast: SDKError surfaces ARE redacted.
	sdk := agentwrap.NewError(agentwrap.ErrorProviderUnavailable, "op", secret, nil)
	if got := mapSDKError(sdk).UserDetail; got != "[REDACTED]" {
		t.Fatalf("mapSDKError user detail = %q", got)
	}
}
EOF
