package runtime

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
)

func TestPruneTargetsWrongRootWhenAmbientXDGAmbientSet(t *testing.T) {
	home := t.TempDir()
	xdg := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("XDG_DATA_HOME", xdg) // ambient environment, NOT in cfg.Agentwrap.Env

	var cfg config.Config
	cfg.Agentwrap.Env = nil // subprocess env = os.Environ()+nil -> sees XDG_DATA_HOME

	stale := time.Now().Add(-72 * time.Hour)
	writeStale := func(root string) string {
		dir := filepath.Join(root, "opencode", "log")
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatal(err)
		}
		p := filepath.Join(dir, "agent.log")
		if err := os.WriteFile(p, []byte("x"), 0o600); err != nil {
			t.Fatal(err)
		}
		if err := os.Chtimes(p, stale, stale); err != nil {
			t.Fatal(err)
		}
		return p
	}
	whereBinaryLogs := writeStale(xdg)   // what the opencode subprocess resolves
	wherePrunerLooks := writeStale(home) // $HOME/.local/share fallback

	if err := pruneOpenCodeLogs(cfg); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(whereBinaryLogs); err == nil {
		t.Logf("CONFIRMED: log the subprocess would write (%s) is never pruned", whereBinaryLogs)
	} else {
		t.Fatalf("unexpectedly removed: %v", err)
	}
	if _, err := os.Stat(wherePrunerLooks); !os.IsNotExist(err) {
		t.Fatalf("pruner did not touch its (wrong) target: %v", err)
	}
}
EOF
go test ./internal/platform/runtime/ -timeout 60s -run TestPruneTargetsWrongRoot -v 2>&1 | tail -8

